        vi.spyOn(cardCommitsHook, 'useCardCommits').mockReturnValue({ commits: [], error: null, loading: false, reload: vi.fn() })
        render(
            <AppThemeProvider>
                <ListEditorToolbarControls
                    cardTypes={[]}
                    historyStore={new MarkdownDocumentHistoryStore()}
                    statusColors={new Map()}
                />
