        fireEvent.click(screen.getByRole('button', { name: 'Agents' }))

        expect(cardActionPopupService.getSnapshot()).toHaveLength(1)
        expect(cardActionPopupService.getSnapshot()[0]?.context).toMatchObject({
            cardInternalId: 'card-060',
            file: card.path,
            kind: 'file',
