        expect(updateTitle).toHaveBeenCalledWith('list-card', 'Renamed')
        expect(updateAuthor).toHaveBeenCalledWith('list-card', 'author', 'AB')
        expect(togglePolicy).toHaveBeenCalledWith('list-card', 'autoMerge')
