import TuneOutlined from '@mui/icons-material/TuneOutlined'
import { IconButton, Tooltip } from '@mui/material'
import { useCallback, useState, type MouseEvent } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import { cardMarkdownDataSource, type CardBinding } from '../editor/card_markdown_data_source'
import { useActiveCard } from '../hooks/use_active_card'
import { CardPropertiesPanel } from './card_properties_panel'
import { CardPropertiesPopover } from './card_properties_popover'

interface CardPropertiesControlProps {
    binding: CardBinding
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

interface PropertiesAnchor {
    documentId: string
    element: HTMLElement
}

/** Icon-only Properties control shared by list and board card toolbars. */
export function CardPropertiesControl(props: CardPropertiesControlProps) {
    const { binding, cardTypes, statusColors } = props
    const card = useActiveCard(binding)
    const documentId = card?.header.internalId ?? null
    const [propertiesAnchor, setPropertiesAnchor] = useState<PropertiesAnchor | null>(null)
    const isOpen = !!documentId && propertiesAnchor?.documentId === documentId

    const handleOpen = useCallback((event: MouseEvent<HTMLElement>) => {
        try {
            const activeDocumentId = cardMarkdownDataSource.getActiveDocument(binding)?.getObject().header.internalId
            if (!activeDocumentId) throw new Error(`Cannot open card properties without an active ${binding} document`)

            setPropertiesAnchor({ documentId: activeDocumentId, element: event.currentTarget })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card properties could not be opened' })
        }
    }, [binding])
    const handleClose = useCallback(() => setPropertiesAnchor(null), [])

    if (!card || !documentId || !card.hasFrontmatter) return null

    return (
        <>
            <Tooltip title="Properties">
                <IconButton
                    aria-haspopup="dialog"
                    aria-label="Properties"
                    onClick={handleOpen}
                    size="small"
                    sx={{
                        bgcolor: isOpen ? 'custom.primaryBg' : 'transparent',
                        color: isOpen ? 'primary.main' : 'inherit',
                        height: 30,
                        width: 30,
                        '&:hover': { bgcolor: 'custom.track', color: 'primary.main' },
                    }}
                >
                    <TuneOutlined sx={{ fontSize: 17 }} />
                </IconButton>
            </Tooltip>
            <CardPropertiesPopover
                anchorElement={isOpen ? propertiesAnchor.element : null}
                onClose={handleClose}
                open={isOpen}
            >
                <CardPropertiesPanel
                    binding={binding}
                    cardTypes={cardTypes}
                    statusColors={statusColors}
                />
            </CardPropertiesPopover>
        </>
    )
}

import { Badge, Box, Divider, IconButton, Popover, Stack, Tooltip, Typography } from '@mui/material'
import SourceCommit from 'mdi-material-ui/SourceCommit'
import type { MouseEvent } from 'react'
import { useState } from 'react'
import { cardCommitLabel, type CardCommit } from '../../services/actions/card_commit_history'
import { dialogService } from '../../services/dialog_service'

interface CardCommitMenuProps {
    commits: CardCommit[]
    currentWorktreeAvailable: boolean
    error: Error | null
    onSelectCommit: (commit: CardCommit) => void
    onSelectWorktree: () => void
}

function commitDate(timestamp: string) {
    return new Intl.DateTimeFormat(undefined, { dateStyle: 'short', timeStyle: 'short' }).format(new Date(timestamp))
}

/** Commit-history menu shared by board-card and file-card surfaces. */
export function CardCommitMenu(props: CardCommitMenuProps) {
    const { commits, currentWorktreeAvailable, error, onSelectCommit, onSelectWorktree } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const handleOpen = (event: MouseEvent<HTMLElement>) => setAnchorElement(event.currentTarget)
    const handleClose = () => setAnchorElement(null)
    const selectCommit = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const commitIndex = Number(event.currentTarget.dataset.commitIndex)
            const commit = commits[commitIndex]
            if (!Number.isInteger(commitIndex) || !commit) throw new Error(`Card commit menu selection not found: ${commitIndex}`)
            onSelectCommit(commit)
            handleClose()
        } catch (caught) {
            dialogService.error(caught, { fallbackMessage: 'Card commit could not be selected' })
        }
    }
    const selectWorktree = () => {
        onSelectWorktree()
        handleClose()
    }

    if (error && !currentWorktreeAvailable) {
        return <Typography color="error" role="alert" title={error.message} variant="caption">Commit history unavailable</Typography>
    }
    if (commits.length === 0 && !currentWorktreeAvailable) return null

    return (
        <>
            <Tooltip title="Card commit history">
                <IconButton aria-label="Card commit history" onClick={handleOpen} size="small" sx={{ height: 30, width: 12, p: 0 }}>
                    <Badge badgeContent={commits.length > 1 ? commits.length : 0} color="primary">
                        <SourceCommit sx={{ fontSize: 17 }} />
                    </Badge>
                </IconButton>
            </Tooltip>
            <Divider orientation="vertical" sx={{ borderColor: 'divider', height: 20 }} />
            <Popover anchorEl={anchorElement} onClose={handleClose} open={!!anchorElement}>
                <Stack sx={{ maxHeight: 360, minWidth: 340, overflowY: 'auto', p: 1 }}>
                    {currentWorktreeAvailable ? (
                        <Box
                            component="button"
                            onClick={selectWorktree}
                            sx={{
                                '&:hover': { bgcolor: 'action.hover' },
                                background: 'none',
                                border: 0,
                                borderRadius: 1,
                                color: 'text.primary',
                                cursor: 'pointer',
                                p: 1,
                                textAlign: 'left',
                            }}
                            type="button"
                        >
                            <Typography variant="body2">Current worktree changes</Typography>
                            <Typography color="text.secondary" variant="caption">Not committed</Typography>
                        </Box>
                    ) : null}
                    {error ? <Typography color="error" role="alert" title={error.message} variant="caption">Commit history unavailable</Typography> : null}
                    {commits.map((commit, commitIndex) => (
                        <Box
                            component="button"
                            data-commit-index={commitIndex}
                            key={`${commit.commit}:${commitIndex}`}
                            onClick={selectCommit}
                            title={commit.commit}
                            sx={{
                                '&:hover': { bgcolor: 'action.hover' },
                                background: 'none',
                                border: 0,
                                borderRadius: 1,
                                color: 'text.primary',
                                cursor: 'pointer',
                                display: 'flex',
                                flexDirection: 'column',
                                p: 1,
                                textAlign: 'left',
                            }}
                            type="button"
                        >
                            <Typography variant="body2">{cardCommitLabel(commit.record)} Â· {commitDate(commit.committedAt)}</Typography>
                            <Typography color="text.secondary" variant="caption">
                                {commit.commit.slice(0, 7)} Â· +{commit.insertions}/âˆ’{commit.deletions}
                            </Typography>
                        </Box>
                    ))}
                </Stack>
            </Popover>
        </>
    )
}

